param([string]$RuntimeRoot=(Join-Path $env:LOCALAPPDATA "Executor"))
$ErrorActionPreference="Stop";Set-StrictMode -Version Latest;$sp=Join-Path $RuntimeRoot "direct-state.json";function P([int]$I,[string]$N){$p=Get-CimInstance Win32_Process -Filter "ProcessId = $I" -ErrorAction SilentlyContinue;if(-not$p){return @{alive=$false;identity_match=$false}};return @{alive=$true;identity_match=([string]$p.CommandLine-like"*$N*")}};if(-not(Test-Path $sp)){[pscustomobject]@{running=$false;state_present=$false}|ConvertTo-Json;return};$s=Get-Content -Raw -Encoding UTF8 $sp|ConvertFrom-Json;$c=P ([int]$s.caddy_pid) "caddy";$co=$false;try{$x=(&(Join-Path $PSScriptRoot "Get-ExecutorControlPlaneStatus.ps1") -RuntimeRoot $RuntimeRoot|Out-String|ConvertFrom-Json);$co=[bool]$x.running}catch{};$lo=$false;try{&(Join-Path $PSScriptRoot "Test-ExecutorDirectReachability.ps1") -PublicDeviceUrl ([string]$s.public_device_url) -CaCertificatePath ([string]$s.ca_certificate_path) -ResolveToLoopback|Out-Null;$lo=$true}catch{};[pscustomobject]@{running=($c.alive-and$c.identity_match-and$co-and$lo);state_present=$true;caddy=$c;control_plane_ok=$co;local_tls_ok=$lo;public_device_url=$s.public_device_url;ca_certificate_path=$s.ca_certificate_path;upnp_mapping_created=$s.upnp_mapping_created}|ConvertTo-Json -Depth 8